{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitchX_cohort_analysis_2 AS ( WITH SnitchX_Members AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CASE WHEN membership_enrolled_date IS NOT NULL AND TRIM(membership_enrolled_date) <> \'\' THEN CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) END AS snitchx_ts FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), MemID_to_Shopify_pre AS ( SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND ros.shopify_user_id IS NOT NULL UNION SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(f.customer_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN snitch_db.maplemonk.FACT_ITEMS_SNITCH f ON RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND f.customer_id IS NOT NULL ), MemID_to_Shopify AS ( SELECT mem_id, MAX(shopify_user_id) AS shopify_user_id FROM MemID_to_Shopify_pre WHERE shopify_user_id IS NOT NULL GROUP BY mem_id ), Offline_Sales AS ( SELECT ros.mem_id, map.shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD,YYYY, HH12:MI AM\') END AS order_ts, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.\-]\',\'\')) ) AS sales, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.\-]\', \'\'))) AS net_sales, ABS(SUM( TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_gross_value), \'[^0-9\.-]\',\'\')) - TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.-]\',\'\')) )) AS discount, COUNT(DISTINCT ros.vouch_time) AS order_count, \'Offline\' AS channel FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id WHERE ros.shopify_user_id IS NOT NULL OR map.shopify_user_id IS NOT NULL GROUP BY ros.mem_id, CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'YYYY-MM-DD HH24:MI:SS\') END, map.shopify_user_id, order_ts ), Online_Sales AS ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, order_timestamp AS order_ts, SUM(IFNULL(gross_sales,0)) AS sales, SUM(CASE WHEN IS_REFUND = 0 THEN COALESCE(gross_sales, 0) ELSE 0 END) AS net_sales, SUM(IFNULL(discount,0)) - SUM(IFNULL(slashed_discount,0)) AS discount, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS order_count, RIGHT(REGEXP_REPLACE(TRIM(CAST(phone AS STRING)),\'[^0-9]\', \'\'),10) AS phone, \'Online\' AS channel FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id IS NOT NULL AND gross_sales <> 0 AND lower(tags) NOT LIKE \'%creator%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\', \'2422237\',\'2420623\',\'2429832\',\'2422378\', \'2428311\',\'2429064\',\'2428204\',\'2421343\', \'2431206\',\'2430491\',\'2426682\',\'2426487\', \'2426458\',\'2423575\',\'2422431\',\'2423612\', \'2426625\',\'2428117\',\'2426894\',\'2425461\', \'2426570\',\'2423455\',\'2430777\',\'2426009\', \'2428245\',\'2427269\',\'2430946\',\'2425821\', \'2429986\',\'2429085\',\'2422047\',\'2430789\', \'2420219\',\'2428341\',\'2430444\',\'2426866\', \'2431230\',\'2425839\',\'2430980\',\'2427048\', \'2430597\',\'2420499\',\'2431050\',\'2420271\', \'2426684\',\'2428747\',\'2423523\',\'2431171\', \'2430830\',\'2425325\',\'2428414\',\'2429054\', \'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1,2,7 ), All_Sales AS ( SELECT shopify_user_id, order_ts, sales, discount, order_count, net_sales, channel FROM Online_Sales UNION ALL SELECT shopify_user_id, order_ts, sales, discount, order_count, net_sales, channel FROM Offline_Sales ), Creator_Users AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE reason ILIKE \'%Creator%\' ), Channel_Tag AS ( SELECT shopify_user_id, MAX(CASE WHEN source=\'Online\' THEN 1 ELSE 0 END) AS has_online, MAX(CASE WHEN source=\'Offline\' THEN 1 ELSE 0 END) AS has_offline FROM ( SELECT DISTINCT shopify_user_id, \'Online\' AS source FROM Online_Sales UNION ALL SELECT DISTINCT COALESCE(ros.shopify_user_id,map.shopify_user_id), \'Offline\' AS source FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN SnitchX_Members map ON ros.mem_id = map.shopify_user_id WHERE ros.mem_id IS NOT NULL ) GROUP BY 1 ), Labeled_Sales AS ( SELECT a.shopify_user_id, a.order_ts, s.snitchx_ts, CASE WHEN a.order_ts <= s.snitchx_ts THEN \'Before\' ELSE \'After\' END AS period, a.sales, a.discount, a.order_count, a.net_sales, a.channel FROM All_Sales a JOIN SnitchX_Members s ON a.shopify_user_id = s.shopify_user_id ), first_credit AS ( SELECT shopify_user_id, amount AS welcome_points FROM ( SELECT shopify_user_id, amount, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY created_at) AS rn FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE type = \'POINTS_CREDIT\' AND reason NOT IN (\'Refund : Online\',\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\') ) sub WHERE rn = 1 ), points_summary AS ( SELECT TRIM(wt.shopify_user_id) AS shopify_user_id, SUM(CASE WHEN wt.type = \'POINTS_CREDIT\' THEN wt.amount ELSE 0 END) AS reward_points_earned, SUM(CASE WHEN wt.type = \'POINTS_DEBIT\' AND wt.reason IN (\'Purchase : Online\', \'Purchase : Store\') THEN ABS(wt.amount) WHEN wt.type = \'POINTS_CREDIT\' AND wt.reason IN (\'Refund : Online\', \'Refund : Store\') THEN -wt.amount ELSE 0 END) AS reward_points_redeemed, SUM(CASE WHEN wt.reason = \'Birthday Bonus\' THEN wt.amount ELSE 0 END) AS birthday_points, SUM(CASE WHEN wt.reason = \'Welcome Bonus\' THEN wt.amount ELSE 0 END) + MAX(COALESCE(fc.welcome_points,0)) AS welcome_points, SUM(CASE WHEN wt.reason ILIKE \'%Bonus%\' AND reason NOT IN (\'Birthday Bonus\',\'Welcome Bonus\') THEN wt.amount ELSE 0 END) AS bonus_points FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db wt LEFT JOIN first_credit fc ON TRIM(wt.shopify_user_id)=fc.shopify_user_id WHERE wt.shopify_user_id IS NOT NULL AND wt.reason NOT IN (\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\') GROUP BY 1 ), Freebies AS ( SELECT TRIM(CAST(shopify_user_id AS STRING)) AS shopify_user_id, COUNT(CASE WHEN gift_reference_id IS NOT NULL AND gift_reference_id <> \'\' THEN shopify_user_id END) AS freebies_received FROM snitch_db.maplemonk.streaks_streaks GROUP BY shopify_user_id ), Streaks AS ( SELECT shopify_user_id, MAX(CASE WHEN streak_count >= 4 AND streak_count < 7 THEN 4 WHEN streak_count >= 7 AND streak_count < 10 THEN 7 WHEN streak_count >= 10 AND streak_count < 13 THEN 10 WHEN streak_count >= 14 THEN 13 ELSE NULL END) AS mapped_streak, MAX(CASE WHEN gift_reference_id <> \'\' THEN TRY_TO_TIMESTAMP(streak_timestamp,\'DD-MM-YYYY HH24:MI\') ELSE NULL END) AS streak_redemption_date FROM snitch_db.maplemonk.streaks_streaks WHERE gift_reference_id <> \'\' AND streak_count > 1 GROUP BY shopify_user_id ), Streak_Previous_Order AS ( SELECT s.shopify_user_id, MAX(TRY_TO_TIMESTAMP(s.streak_timestamp,\'DD-MM-YYYY HH24:MI\')) AS streak_redemption_date, MAX(TRY_TO_TIMESTAMP(p.streak_timestamp,\'DD-MM-YYYY HH24:MI\')) AS streak_previous_order FROM snitch_db.maplemonk.streaks_streaks s LEFT JOIN snitch_db.maplemonk.streaks_streaks p ON s.shopify_user_id = p.shopify_user_id AND TRY_TO_TIMESTAMP(p.streak_timestamp,\'DD-MM-YYYY HH24:MI\') < TRY_TO_TIMESTAMP(s.streak_timestamp,\'DD-MM-YYYY HH24:MI\') WHERE s.gift_reference_id <> \'\' AND s.streak_count > 1 GROUP BY s.shopify_user_id ), Items_Ordered AS ( SELECT o.customer_id AS shopify_user_id, SUM(CASE WHEN o.order_timestamp < sm.snitchx_ts THEN IFNULL(o.quantity,0) ELSE 0 END) AS items_before_enrollment, SUM(CASE WHEN o.order_timestamp >= sm.snitchx_ts THEN IFNULL(o.quantity,0) ELSE 0 END) AS items_after_enrollment FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH o JOIN SnitchX_Members sm ON o.customer_id = sm.shopify_user_id WHERE o.customer_id IS NOT NULL AND LOWER(o.order_status) NOT LIKE \'%cancel%\' GROUP BY o.customer_id ), Returns AS ( SELECT f.customer_id AS shopify_user_id, COUNT( CASE WHEN f.order_timestamp >= CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END THEN 1 END ) AS returns_after_enollment, SUM( CASE WHEN f.order_timestamp >= CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END THEN f.line_item_sales ELSE 0 END ) AS return_value, COUNT( CASE WHEN f.order_timestamp < CAST( CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END AS DATE) AND f.order_timestamp >= CAST( CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END AS DATE) - INTERVAL \'12 months\' THEN 1 END ) AS returns_before_enollment FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH f JOIN snitch_db.maplemonk.s3_bucket_wallet_db w ON f.customer_id = w.shopify_user_id WHERE (f.IS_REFUND = 1 OR f.return_flag = 1) AND LOWER(f.order_status) NOT LIKE \'%cancel%\' AND w.membership_enrolled_date IS NOT NULL AND TRIM(w.membership_enrolled_date) <> \'\' GROUP BY f.customer_id ), Cohort_Builder AS ( SELECT shopify_user_id, snitchx_ts::DATE AS snitchx_date, MAX(CASE WHEN period=\'Before\' THEN order_ts END)::DATE AS not_snitchx_purchase_date, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN net_sales ELSE 0 END) AS not_snitchx_purchase_value, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN discount ELSE 0 END) AS not_snitchx_purchase_discount, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN channel END) AS not_snitchx_purchase_channel, MAX(CASE WHEN period=\'After\' THEN order_ts END)::DATE AS last_purchase_date, MIN(CASE WHEN period=\'After\' THEN order_ts END)::DATE AS first_purchase_date, MIN(CASE WHEN period=\'Before\' THEN order_ts END)::DATE AS first_purchase_date_pre_enroll, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(net_sales,0) END) AS net_spend_l12, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(discount,0) END) AS total_discount_before, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(order_count,0) END) AS order_count_before, SUM(CASE WHEN period=\'After\' THEN discount ELSE 0 END) AS total_discount_after, SUM(CASE WHEN period=\'After\' THEN order_count ELSE 0 END) AS order_count_after, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts THEN IFNULL(sales,0) END) AS net_sales_post_enrollment, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts AND order_ts <= \'2025-03-15\' THEN IFNULL(sales,0) END) AS net_sales_post_enrollment_march15, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts AND order_ts < DATEADD(month,1,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_1, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,1,snitchx_ts) AND order_ts < DATEADD(month,2,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_2, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,2,snitchx_ts) AND order_ts < DATEADD(month,3,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_3, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,3,snitchx_ts) AND order_ts < DATEADD(month,4,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_4, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,4,snitchx_ts) AND order_ts < DATEADD(month,5,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_5, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,5,snitchx_ts) AND order_ts < DATEADD(month,6,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_6, SUM(CASE WHEN period=\'After\' THEN net_sales END) AS net_sales, DATEDIFF(day,snitchx_ts::DATE,CURRENT_DATE()) AS days_since_enrollment, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATEADD(day,-365,snitchx_ts) AND order_ts <= DATEADD(day, DATEDIFF(day,snitchx_ts::DATE,CURRENT_DATE())-365, snitchx_ts) THEN IFNULL(sales,0) END) AS net_sales_baseline FROM Labeled_Sales GROUP BY 1,2 ), Month_Order AS ( SELECT c.shopify_user_id, c.first_purchase_date, SUM(CASE WHEN order_ts >= CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN DATE_TRUNC(\'MONTH\', NOT_SNITCHX_PURCHASE_DATE) ELSE DATE_TRUNC(\'MONTH\', FIRST_PURCHASE_DATE) END AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_1, COUNT(CASE WHEN order_ts >= CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN DATE_TRUNC(\'MONTH\', NOT_SNITCHX_PURCHASE_DATE) ELSE DATE_TRUNC(\'MONTH\', FIRST_PURCHASE_DATE) END AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_1, SUM(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_2, COUNT(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_2, SUM(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 3, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_3, COUNT(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 3, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_3 FROM Cohort_Builder c JOIN Labeled_Sales l ON l.shopify_user_id = c.shopify_user_id GROUP BY c.shopify_user_id, c.first_purchase_date ), Month_Order_YearAgo AS ( SELECT c.shopify_user_id, c.first_purchase_date, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,first_purchase_date)) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_1, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,first_purchase_date)) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_1, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_2, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_2, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_3, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,4,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_4, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,4,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,5,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_5, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,5,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,6,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_6, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,6,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,7,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_7, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,7,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,8,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_8, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,8,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,9,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_9, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,9,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,10,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_10, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,10,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,11,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_11, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,11,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,12,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_12, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_3 FROM Cohort_Builder c JOIN Labeled_Sales l ON l.shopify_user_id = c.shopify_user_id GROUP BY 1,2 ), Min_Enrollment_Date AS ( SELECT DATE_TRUNC(\'month\', MIN(snitchx_ts)) AS min_month FROM SnitchX_Members WHERE snitchx_ts IS NOT NULL ), Month_Series AS ( SELECT min_month AS month_start, DATEADD(day,-1,DATEADD(month,1,min_month)) AS month_end FROM Min_Enrollment_Date UNION ALL SELECT DATEADD(month,1,month_start), DATEADD(day,-1,DATEADD(month,2,month_start)) FROM Month_Series WHERE DATEADD(month,1,month_start) <= DATE_TRUNC(\'month\',CURRENT_DATE()) ), Month_Factors AS ( SELECT 4 AS month_num, 0.080 AS factor UNION ALL SELECT 5 AS month_num, 0.085 AS factor UNION ALL SELECT 6 AS month_num, 0.078 AS factor UNION ALL SELECT 7 AS month_num, 0.083 AS factor UNION ALL SELECT 8 AS month_num, 0.079 AS factor UNION ALL SELECT 9 AS month_num, 0.088 AS factor UNION ALL SELECT 10 AS month_num, 0.102 AS factor UNION ALL SELECT 11 AS month_num, 0.079 AS factor UNION ALL SELECT 12 AS month_num, 0.087 AS factor UNION ALL SELECT 1 AS month_num, 0.072 AS factor UNION ALL SELECT 2 AS month_num, 0.065 AS factor UNION ALL SELECT 3 AS month_num, 0.100 AS factor ), Enrollment_Months AS ( SELECT c.shopify_user_id, ms.month_start, ms.month_end, c.snitchx_date FROM Cohort_Builder c JOIN Month_Series ms ON ms.month_start >= DATE_TRUNC(\'month\',c.snitchx_date) AND ms.month_start <= DATE_TRUNC(\'month\',CURRENT_DATE()) ), Weighted_Factor AS ( SELECT e.shopify_user_id, SUM( CASE WHEN coverage_end >= coverage_start THEN (DATEDIFF(day,coverage_start,coverage_end)+1)::DECIMAL(10,2) * mf.factor / (DATEDIFF(day,e.month_start,e.month_end)+1) ELSE 0 END ) AS overall_net_factor FROM ( SELECT shopify_user_id, month_start, month_end, GREATEST(month_start,snitchx_date) AS coverage_start, LEAST(month_end,CURRENT_DATE()) AS coverage_end FROM Enrollment_Months ) e JOIN Month_Factors mf ON EXTRACT(MONTH FROM e.month_start) = mf.month_num GROUP BY 1 ), Phone_Map AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, \'+91\' || RIGHT(REGEXP_REPLACE(TRIM(mem_id),\'[^0-9]\',\'\'),10) AS phone FROM snitch_db.maplemonk.retail_orders_summary_retail_order_summary WHERE mem_id IS NOT NULL AND shopify_user_id != \'\' AND LENGTH(REGEXP_REPLACE(TRIM(mem_id),\'[^0-9]\',\'\')) >= 10 UNION ALL SELECT TRIM(customer_id) AS shopify_user_id, \'+91\' || RIGHT(REGEXP_REPLACE(TRIM(phone),\'[^0-9]\',\'\'),10) AS phone FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE phone IS NOT NULL AND customer_id IS NOT NULL AND LENGTH(REGEXP_REPLACE(TRIM(phone),\'[^0-9]\',\'\')) >= 10 ), Phone_Map_dedup AS ( SELECT shopify_user_id, MIN(phone) AS phone FROM Phone_Map GROUP BY shopify_user_id ), User_Cohorts AS ( SELECT c.shopify_user_id, pm.phone AS phone, c.snitchx_date, c.not_snitchx_purchase_date, c.not_snitchx_purchase_channel, c.not_snitchx_purchase_value, c.not_snitchx_purchase_discount, c.first_purchase_date, c.first_purchase_date_pre_enroll, c.last_purchase_date, c.net_spend_l12, c.net_sales, c.order_count_before, c.order_count_after, c.total_discount_before, c.total_discount_after, c.net_sales_post_enrollment, c.net_sales_post_enrollment_march15, c.sales_month_1, c.sales_month_2, c.sales_month_3, c.sales_month_4, c.sales_month_5, c.sales_month_6, mo.new_sales_month_1, mo.new_orders_month_1, mo.new_sales_month_2, mo.new_orders_month_2, mo.new_sales_month_3, mo.new_orders_month_3, mya.prev_year_sales_month_1, mya.prev_year_orders_month_1, mya.prev_year_sales_month_2, mya.prev_year_orders_month_2, mya.prev_year_sales_month_3, mya.prev_year_sales_month_4, mya.prev_year_sales_month_5, mya.prev_year_sales_month_6, mya.prev_year_sales_month_7, mya.prev_year_sales_month_8, mya.prev_year_sales_month_9, mya.prev_year_sales_month_10, mya.prev_year_sales_month_11, mya.prev_year_sales_month_12, mya.prev_year_orders_month_3, c.net_sales_baseline, c.days_since_enrollment, ps.reward_points_earned, ps.reward_points_redeemed, ps.welcome_points, ps.birthday_points, ps.bonus_points, f.freebies_received, s.mapped_streak, s.streak_redemption_date, p.streak_previous_order, DATEDIFF(day,p.streak_previous_order,s.streak_redemption_date) AS streak_TAT, COALESCE(i.items_before_enrollment,0) AS items_before_enrollment, r.returns_before_enollment, COALESCE(i.items_after_enrollment,0) AS items_after_enrollment, r.returns_after_enollment, r.return_value, CASE WHEN net_spend_l12 >= 15000 THEN \'15000+\' WHEN net_spend_l12 >= 13000 THEN \'13000-15000\' WHEN net_spend_l12 >= 11000 THEN \'11000-13000\' WHEN net_spend_l12 >= 9000 THEN \'9000-11000\' WHEN net_spend_l12 >= 7000 THEN \'7000-9000\' WHEN net_spend_l12 >= 5000 THEN \'5000-7000\' ELSE \'Below 5000\' END AS user_cohort, CASE WHEN net_spend_l12 >= 15000 THEN 6 WHEN net_spend_l12 >= 13000 THEN 5 WHEN net_spend_l12 >= 11000 THEN 4 WHEN net_spend_l12 >= 9000 THEN 3 WHEN net_spend_l12 >= 7000 THEN 2 WHEN net_spend_l12 >= 5000 THEN 1 ELSE 0 END AS cohort_id, CASE WHEN ct.has_online = 1 AND ct.has_offline = 1 THEN \'Both\' WHEN ct.has_online = 1 THEN \'Online\' WHEN ct.has_offline = 1 THEN \'Offline\' ELSE \'None\' END AS channel FROM Cohort_Builder c LEFT JOIN Channel_Tag ct ON c.shopify_user_id = ct.shopify_user_id LEFT JOIN points_summary ps ON c.shopify_user_id = ps.shopify_user_id LEFT JOIN Freebies f ON c.shopify_user_id = f.shopify_user_id LEFT JOIN Streaks s ON c.shopify_user_id = s.shopify_user_id LEFT JOIN Streak_Previous_Order p ON c.shopify_user_id = p.shopify_user_id LEFT JOIN Returns r ON r.shopify_user_id = c.shopify_user_id LEFT JOIN Items_Ordered i ON c.shopify_user_id = i.shopify_user_id LEFT JOIN Month_Order mo ON c.shopify_user_id = mo.shopify_user_id LEFT JOIN Month_Order_YearAgo mya ON c.shopify_user_id = mya.shopify_user_id LEFT JOIN Phone_Map_dedup pm ON c.shopify_user_id = pm.shopify_user_id ) SELECT uc.*, COALESCE(wf.overall_net_factor,0) AS overall_net_factor FROM User_Cohorts uc LEFT JOIN Weighted_Factor wf ON uc.shopify_user_id = wf.shopify_user_id WHERE uc.shopify_user_id NOT IN (SELECT shopify_user_id FROM Creator_Users) );",
                    "transaction": true
                }
            ) }}
